void log_init(const char * name, int isdaemon, int verbose) /* <=== log_init */ 
{
	if (logpriv)
		return;

	logpriv = malloc(sizeof(struct logpriv_s));
	if (!logpriv)
		return;

	if (name)
		logpriv->name = strdup(name);
	else
		logpriv->name = strdup(LOG_NAME_DEFAULT);

	if (!logpriv->name)
		fprintf(stderr, "ipmitool: malloc failure\n");

	logpriv->daemon = isdaemon;
	logpriv->level = verbose + LOG_NOTICE;

	if (logpriv->daemon)
		openlog(logpriv->name, LOG_CONS, LOG_LOCAL4);
}

static inline bool fru_cc_rq2big(int code) { /* <=== fru_cc_rq2big */ 
	return (code == IPMI_CC_REQ_DATA_INV_LENGTH
		|| code == IPMI_CC_REQ_DATA_FIELD_EXCEED
		|| code == IPMI_CC_CANT_RET_NUM_REQ_BYTES);
}

static /* <=== unknown_val_str */ 
inline
const char *unknown_val_str(uint32_t val)
{
	static char un_str[32];
	memset(un_str, 0, 32);
	snprintf(un_str, 32, "Unknown (0x%02X)", val);

	return un_str;
}

const char * /* <=== specific_val2str */ 
specific_val2str(uint32_t val,
                 const struct valstr *specific,
                 const struct valstr *generic)
{
	int i;

	if (0 <= (i = find_val_idx(val, specific))) {
		return specific[i].str;
	}

	if (0 <= (i = find_val_idx(val, generic))) {
		return generic[i].str;
	}

	return unknown_val_str(val);
}

static /* <=== find_val_idx */ 
inline
off_t find_val_idx(uint32_t val, const struct valstr *vs)
{
	if (vs) {
		for (off_t i = 0; vs[i].str; ++i) {
			if (vs[i].val == val) {
				return i;
			}
		}
	}

	return -1;
}

const char *val2str(uint32_t val, const struct valstr *vs) /* <=== val2str */ 
{
	return specific_val2str(val, NULL, vs);
}

void lprintf(int level, const char * format, ...) /* <=== lprintf */ 
{
	static char logmsg[LOG_MSG_LENGTH];
	va_list vptr;

	if (!logpriv)
		log_reinit();

	if (logpriv->level < level)
		return;

	va_start(vptr, format);
	vsnprintf(logmsg, LOG_MSG_LENGTH, format, vptr);
	va_end(vptr);

	if (logpriv->daemon)
		syslog(level, "%s", logmsg);
	else
		fprintf(stderr, "%s\n", logmsg);
	return;
}

